  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 100;
  transition: top .15s;
}
.skip-link:focus { top: 12px; }

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(251, 250, 247, 0.92);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 68px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark { color: var(--brand); }
.brand-name {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.primary-nav {
  flex: 1;
  display: flex;
  justify-content: center;
}
.primary-nav ul {
  display: flex;
  gap: 28px;
}
.primary-nav a {
  text-decoration: none;
  color: var(--ink);
  font-size: 0.95rem;
  padding: 8px 4px;
  position: relative;
}
.primary-nav a:hover { color: var(--brand); }
.primary-nav a::after {
  content: "";
  position: absolute;
  left: 4px; right: 4px; bottom: 2px;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .2s ease;
}
.primary-nav a:hover::after { transform: scaleX(1); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--ink);
  width: 40px; height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  cursor: pointer;
  position: relative;
  transition: background .15s, border-color .15s;
}
.icon-btn:hover { background: var(--bg-muted); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--ink);
  color: var(--accent-ink);
  font-size: 0.65rem;
  font-weight: 600;
  min-width: 16px; height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

@media (max-width: 720px) {
  .primary-nav { display: none; }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 0.95rem;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  transition: transform .12s, background .15s, border-color .15s, color .15s;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--ink);
  color: var(--accent-ink);
  border-color: var(--ink);
}
.btn-primary:hover { background: #2c2c2c; }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-ghost:hover { background: var(--ink); color: var(--accent-ink); }

.link-arrow {
  text-decoration: none;
  color: var(--ink);
  font-weight: 500;
  font-size: 0.95rem;
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
}
.link-arrow:hover { color: var(--brand); border-color: var(--brand); }

/* ---------- Hero ---------- */
.hero {
  padding: 64px 0 48px;
  overflow: hidden;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 14px;
}
.hero-lede {
  font-size: 1.1rem;
  color: var(--ink-muted);
  margin: 20px 0 28px;
  max-width: 52ch;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.hero-art {
  position: relative;
  aspect-ratio: 1 / 0.95;
  min-height: 360px;
}
.hero-card {
  position: absolute;
  border-radius: var(--radius);
  box-shadow: var(--shadow-md);
}
.hero-card-1 {
  inset: 0 32% 28% 0;
  background:
    radial-gradient(circle at 30% 30%, #e8d3b6 0%, #c9a878 100%);
}
.hero-card-2 {
  inset: 22% 0 0 38%;
  background:
    radial-gradient(circle at 70% 30%, #d4dccd 0%, #8aa07b 100%);
}
.hero-card-3 {
  inset: 56% 50% 0 12%;
  background:
    radial-gradient(circle at 40% 60%, #f0d4cb 0%, #c97f6c 100%);
}

@media (max-width: 820px) {
  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
  .hero-art { min-height: 280px; }
}

/* ---------- Categories ---------- */
.categories {
  border-block: 1px solid var(--line);
  padding: 18px 0;
  background: var(--surface);
}
.category-list {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  scrollbar-width: thin;
  padding-bottom: 4px;
}
.category-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  text-decoration: none;
  color: var(--ink);
  font-size: 0.9rem;
  white-space: nowrap;
  background: var(--bg);
  transition: border-color .15s, background .15s;
}
.category-pill:hover { border-color: var(--ink); }
.cat-dot {
  width: 10px; height: 10px;
  border-radius: 999px;
  background: var(--c, var(--brand));
  border: 1px solid rgba(0,0,0,0.08);
}

/* ---------- Sections ---------- */
.section {
  padding: 72px 0;
}
.section-muted { background: var(--bg-muted); }

.section-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

/* ---------- Product Grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px 24px;
}
.product-card {
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: transparent;
}
.product-link {
  display: block;
  text-decoration: none;
  color: inherit;
}
.product-image {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg-muted);
  transition: transform .3s ease;
}
.product-link:hover .product-image { transform: translateY(-2px); }
.product-image-inner {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: 3rem;
  color: rgba(255,255,255,.7);
}
.product-badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--surface);
  color: var(--ink);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
  box-shadow: var(--shadow-sm);
}
.product-badge-sale { background: var(--sale); color: #fff; }

.product-meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 6px;
}
.product-name {
  font-size: 0.98rem;
  font-weight: 500;
  color: var(--ink);
  margin: 0;
}
.product-category {
  font-size: 0.82rem;
  color: var(--ink-soft);
  margin-top: 2px;
}
.product-price {
  font-size: 0.98rem;
  font-weight: 500;
  color: var(--ink);
  white-space: nowrap;
}
.price-old {
  color: var(--ink-soft);
  text-decoration: line-through;
  margin-right: 6px;
  font-weight: 400;
}
.price-new { color: var(--sale); font-weight: 600; }

.add-btn {
  margin-top: 8px;
  padding: 10px 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  color: var(--ink);
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s;
}
.add-btn:hover { background: var(--ink); color: var(--accent-ink); border-color: var(--ink); }

@media (max-width: 980px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px) { .product-grid { grid-template-columns: repeat(2, 1fr); gap: 22px 16px; } }

/* ---------- Deals ---------- */
.deal-timer {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 0.9rem;
}
.timer-label { color: var(--ink-soft); font-size: 0.82rem; }
.timer-value {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--sale);
  letter-spacing: 0.02em;
}

.deal-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.deal-card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  display: flex;
  gap: 20px;
  align-items: center;
  border: 1px solid var(--line);
  transition: transform .2s, box-shadow .2s;
}
.deal-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.deal-art {
  width: 96px;
  height: 96px;
  border-radius: 12px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: 1.6rem;
  color: rgba(255,255,255,.85);
}
.deal-body { flex: 1; min-width: 0; }
.deal-discount {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--sale);
  margin-bottom: 6px;
}
.deal-title {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 4px;
}
.deal-desc {
  font-size: 0.88rem;
  color: var(--ink-muted);
  margin-bottom: 8px;
  overflow-wrap: anywhere;
}
.deal-price { font-size: 0.95rem; }

@media (max-width: 980px) { .deal-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .deal-grid { grid-template-columns: 1fr; } }

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  grid-template-rows: auto auto;
  gap: 24px;
}
.editorial-feature { grid-row: span 2; }
.editorial-link {
  display: block;
  text-decoration: none;
  color: inherit;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line);
  height: 100%;
  transition: transform .2s, box-shadow .2s;
}
.editorial-link:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.editorial-image {
  aspect-ratio: 16 / 10;
  background-size: cover;
  background-position: center;
}
.editorial-feature .editorial-image { aspect-ratio: 4 / 5; }
.editorial-image-1 {
  background:
    radial-gradient(circle at 30% 40%, #d4b78c 0%, #6b5d4f 100%);
}
.editorial-image-2 {
  background:
    linear-gradient(135deg, #c2c8b8 0%, #7d8a73 100%);
}
.editorial-image-3 {
  background:
    linear-gradient(135deg, #e0c5b9 0%, #8a6a5e 100%);
}
.editorial-body { padding: 24px; }
.editorial-feature .editorial-body { padding: 28px; }
.editorial-feature h3 { font-size: 1.6rem; margin: 8px 0 10px; }
.editorial-card h3 { font-size: 1.15rem; margin-bottom: 8px; }
.editorial-excerpt {
  color: var(--ink-muted);
  font-size: 0.95rem;
  margin-bottom: 12px;
}
.editorial-meta {
  font-size: 0.78rem;
  color: var(--ink-soft);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

@media (max-width: 820px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-feature { grid-row: auto; }
}

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--ink);
  color: var(--accent-ink);
  padding: 72px 0;
}
.newsletter h2 { color: var(--accent-ink); }
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.newsletter-copy p {
  color: rgba(251, 250, 247, 0.78);
  margin-top: 12px;
  max-width: 42ch;
}
.newsletter-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: start;
}
.newsletter-form input {
  padding: 14px 18px;
  border-radius: 999px;
  border: 1px solid rgba(251, 250, 247, 0.25);
  background: rgba(255,255,255,0.06);
  color: var(--accent-ink);
  font: inherit;
  min-width: 0;
}
.newsletter-form input::placeholder { color: rgba(251, 250, 247, 0.55); }
.newsletter-form input:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
  border-color: transparent;
}
.newsletter-form input[aria-invalid="true"] {
  border-color: #ff9a8a;
}
.newsletter-form .btn-primary {
  background: var(--accent-ink);
  color: var(--ink);
  border-color: var(--accent-ink);
}
.newsletter-form .btn-primary:hover { background: #e8e3d6; }
.form-help, .form-error, .form-success {
  grid-column: 1 / -1;
  font-size: 0.85rem;
  margin-top: 4px;
}
.form-help { color: rgba(251, 250, 247, 0.65); }
.form-error { color: #ffb2a3; }
.form-success { color: #a8e6b8; }

@media (max-width: 820px) {
  .newsletter-inner { grid-template-columns: 1fr; gap: 24px; }
}
@media (max-width: 520px) {
  .newsletter-form { grid-template-columns: 1fr; }
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--bg-muted);
  border-top: 1px solid var(--line);
  padding: 56px 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}
.footer-brand p {
  margin-top: 12px;
  color: var(--ink-muted);
  max-width: 36ch;
  font-size: 0.92rem;
}
.footer-heading {
  font-family: var(--font-sans);
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink);
  margin-bottom: 14px;
}
.site-footer nav ul { display: grid; gap: 8px; }
.site-footer nav a {
  text-decoration: none;
  color: var(--ink-muted);
  font-size: 0.92rem;
}
.site-footer nav a:hover { color: var(--ink); text-decoration: underline; }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  color: var(--ink-soft);
  font-size: 0.85rem;
  flex-wrap: wrap;
  gap: 8px;
}

@media (max-width: 820px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 520px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* ---------- Forced colors ---------- */
@media (forced-colors: active) {
  .btn-primary, .icon-btn, .add-btn {
    border: 1px solid ButtonBorder;
  }
  .product-image, .deal-art, .hero-card, .editorial-image {
    border: 1px solid CanvasText;
  }
  :focus-visible { outline: 2px solid Highlight; }
  .newsletter { background: Canvas; color: CanvasText; }
  .newsletter h2, .newsletter-copy p { color: CanvasText; }
}

