  `).join("");
}

// ---------- Cart ----------
let cartCount = 0;
function updateCart(n) {
  cartCount += n;
  const el = document.getElementById("cart-count");
  const btn = document.getElementById("cart-btn");
  if (el) el.textContent = cartCount;
  if (btn) btn.setAttribute("aria-label", `Cart, ${cartCount} item${cartCount === 1 ? "" : "s"}`);
}

function bindAddButtons() {
  document.querySelectorAll(".add-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      updateCart(1);
      const original = btn.textContent;
      btn.textContent = "Added ✓";
      btn.disabled = true;
      setTimeout(() => {
        btn.textContent = original;
        btn.disabled = false;
      }, 1400);
    });
  });
}

// ---------- Countdown timer ----------
function startTimer() {
  const el = document.getElementById("timer");
  if (!el) return;
  // Ends at next midnight (local)
  const end = new Date();
  end.setHours(24, 0, 0, 0);

  function tick() {
    const ms = end - new Date();
    if (ms <= 0) { el.textContent = "00:00:00"; return; }
    const h = Math.floor(ms / 3600000);
    const m = Math.floor((ms % 3600000) / 60000);
    const s = Math.floor((ms % 60000) / 1000);
    const pad = (n) => String(n).padStart(2, "0");
    el.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
  }
  tick();
  setInterval(tick, 1000);
}

// ---------- Newsletter form ----------
function bindNewsletter() {
  const form = document.getElementById("newsletter-form");
  if (!form) return;
  const input = document.getElementById("email");
  const error = document.getElementById("email-error");
  const success = document.getElementById("email-success");

  const isEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    success.textContent = "";
    const value = input.value.trim();
    if (!value) {
      showError("Please enter your email address.");
      return;
    }
    if (!isEmail(value)) {
      showError("Please enter a valid email address (e.g. you@example.com).");
      return;
    }
    clearError();
    success.textContent = `Thanks — we'll be in touch at ${value}.`;
    form.reset();
  });

  input.addEventListener("input", () => {
    if (input.getAttribute("aria-invalid") === "true") clearError();
  });

  function showError(msg) {
    input.setAttribute("aria-invalid", "true");
    error.textContent = msg;
    error.hidden = false;
    input.focus();
  }
  function clearError() {
    input.removeAttribute("aria-invalid");
    error.hidden = true;
    error.textContent = "";
  }
}

// ---------- Init ----------
document.addEventListener("DOMContentLoaded", () => {
  renderFeatured();
  renderDeals();
  bindAddButtons();
  startTimer();
  bindNewsletter();
});
